def substring_range(text, start_index, end_index):
    result = ''
    index = start_index
    while (index < end_index):
        result = (result + text[index])
        index = (index + 1)
    return result

def sublist_range(values, start_index, end_index):
    result = []
    index = start_index
    while (index < end_index):
        result.append(values[index])
        index = (index + 1)
    return result

def clean_text(t):
    t = t.replace('’', "'")
    t = t.replace('‘', "'")
    t = t.replace('“', '"')
    t = t.replace('”', '"')
    t = t.replace('—', '-')
    t = t.replace('–', '-')
    t = t.replace('…', '...')
    return t

