def split_sentences(text):
    temp = text.replace('?', '.').replace('!', '.')
    parts = temp.split('.')
    sentences = []
    i = 0
    loop = True
    while loop:
        try:
            s = parts[i].strip()
            if (len(s) > 0):
                sentences.append(s)
            i = (i + 1)
        except Exception:
            loop = False
    return sentences

