def rewrite_answer(sentence, question_type):
    words = tokenise(sentence)
    if (len(words) > 0):
        if (words[0] == 'because'):
            words = sublist_range(words, 1, len(words))
    if (question_type == 'where'):
        i = 0
        loop = True
        while loop:
            try:
                if (words[i] == 'at'):
                    words[i] = 'in'
                i = (i + 1)
            except Exception:
                loop = False
    if (question_type == 'why'):
        i = 0
        loop = True
        start = 0
        while loop:
            try:
                if (words[i] == 'because'):
                    start = i
                i = (i + 1)
            except Exception:
                loop = False
        words = sublist_range(words, start, len(words))
    if (question_type == 'who'):
        if (len(words) > 8):
            new_words = []
            j = 0
            loop2 = True
            while loop2:
                try:
                    if (j < 8):
                        new_words.append(words[j])
                    j = (j + 1)
                except Exception:
                    loop2 = False
            words = new_words
    if (question_type == 'what'):
        i = 0
        loop = True
        start = 0
        found = False
        while loop:
            try:
                if (words[i] == 'for'):
                    start = i
                    found = True
                i = (i + 1)
            except Exception:
                loop = False
        if found:
            new_words = []
            j = start
            loop2 = True
            while loop2:
                try:
                    new_words.append(words[j])
                    j = (j + 1)
                except Exception:
                    loop2 = False
            words = new_words
    rewritten = ''
    i = 0
    loop = True
    while loop:
        try:
            rewritten = (rewritten + (words[i] + ' '))
            i = (i + 1)
        except Exception:
            loop = False
    return rewritten.strip()

